      "nets": ["GND"],
      "observed": "Both isolated CAN transceivers have GND1 and GND2 connected to the same GND net.",
      "expected": "For the specified isolated CAN interfaces, the transceivers' logic-side and bus-side grounds must remain separate; the bus side also requires an isolated supply.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(node (ref \"U1\") (pin \"4\") (pinfunction \"GND1\") ...)\n(node (ref \"U1\") (pin \"5\") (pinfunction \"GND2\") ...)\n(node (ref \"U12\") (pin \"4\") (pinfunction \"GND1\") ...)\n(node (ref \"U12\") (pin \"5\") (pinfunction \"GND2\") ...)"
        },
        {
          "source": "spec",
          "quote": "two isolated CAN buses"
        }
      ],
      "impact": "The ground connection defeats galvanic isolation on both CAN interfaces, allowing ground-potential differences and ground-loop or transient currents to pass between the bus side and the controller side.",
      "confidence": 0.96
    }
  ],
  "summary": "The CAN transceivers are described as isolated, but their logic-side and bus-side ground pins are all tied to GND. This defeats the specified galvanic isolation."
}

